struct ListNode *reverseBetween(struct ListNode *head, int left, int right) {
  struct ListNode dummy;
  dummy.next = head;
  struct ListNode *pre = &dummy;
  for (int i = 0; i < left - 1; i++) {
    pre = pre->next;
  }
  struct ListNode *cur = pre->next;
  for (int i = 0; i < right - left; i++) {
    struct ListNode *next = cur->next;
    cur->next = next->next;
    next->next = pre->next;
    pre->next = next;
  }
  return dummy.next;
}

func reverseBetween(head *ListNode, left int, right int) *ListNode {
	dummy := &ListNode{Next: head}
	pre := dummy
	for i := 0; i < left-1; i++ {
		pre = pre.Next
	}
	cur := pre.Next
	for i := 0; i < right-left; i++ {
		next := cur.Next
		cur.Next = next.Next
		next.Next = pre.Next
		pre.Next = next
	}
	return dummy.Next
}

class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  public ListNode reverseBetween(ListNode head, int left, int right) {
    ListNode dummy = new ListNode(0);
    dummy.next = head;
    ListNode pre = dummy;
    for (int i = 0; i < left - 1; i++) {
      pre = pre.next;
    }
    ListNode cur = pre.next;
    for (int i = 0; i < right - left; i++) {
      ListNode next = cur.next;
      cur.next = next.next;
      next.next = pre.next;
      pre.next = next;
    }
    return dummy.next;
  }
}

impl Solution {
  pub fn reverse_between(
    head: Option<Box<ListNode>>,
    left: i32,
    right: i32,
  ) -> Option<Box<ListNode>> {
    let mut vals = vec![];
    let mut cur = head;
    while let Some(node) = cur {
      vals.push(node.val);
      cur = node.next;
    }
    let (l, r) = (left as usize - 1, right as usize);
    vals[l..r].reverse();

    let mut dummy = ListNode::new(0);
    let mut tail = &mut dummy;
    for v in vals {
      tail.next = Some(Box::new(ListNode::new(v)));
      tail = tail.next.as_mut().unwrap();
    }
    dummy.next
  }
}

const reverseBetween = (head: ListNode | null, left: number, right: number): ListNode | null => {
  const dummy = new ListNode(0, head);
  let pre: ListNode = dummy;
  for (let i = 0; i < left - 1; i++) pre = pre.next!;
  let cur = pre.next!;
  for (let i = 0; i < right - left; i++) {
    const next = cur.next!;
    cur.next = next.next;
    next.next = pre.next;
    pre.next = next;
  }
  return dummy.next;
};
